import { Question } from '@/types/question';

const questions: Question[] = [
  { id: 'ai-engineer-mlops-l4-001', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Experiment Tracking', question: 'What is the "experiment reproducibility crisis" in ML and how do tools like MLflow, W&B, and DVC address it?', options: ['ML experiments depend on code, data, hyperparameters, random seeds, library versions, and hardware — any change can alter results. MLflow tracks parameters/metrics/artifacts, W&B adds system metrics and collaboration, DVC versions large datasets alongside code in Git. Full reproducibility requires pinning all of: code commit, data version, environment (Docker), config, and hardware specs', 'Only the model weights need to be saved for reproducibility', 'Random seeds alone guarantee exact reproducibility', 'ML experiments are always perfectly reproducible'], correctAnswer: 0, explanation: 'A "reproducible" ML experiment requires: (1) code version (git SHA), (2) data version (DVC hash or data snapshot), (3) environment (Docker image with pinned dependencies), (4) config (hyperparameters, architecture choices), (5) random seeds, (6) hardware spec (GPU type affects numerical results due to different floating-point implementations). Tools address subsets: MLflow/W&B handle params+metrics+artifacts, DVC handles data versioning, Docker handles environment. Full reproducibility also requires deterministic operations (torch.use_deterministic_algorithms(True)), which can be slower.', tags: ['reproducibility', 'mlflow', 'wandb', 'dvc'] },
  { id: 'ai-engineer-mlops-l4-002', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Model Registry', question: 'What is a model registry and what metadata should it track beyond model weights?', options: ['A model registry stores model artifacts along with: training data lineage (which dataset version), evaluation metrics across multiple datasets/slices, model card (intended use, limitations, biases), deployment status (staging/production), approval chain (who reviewed), dependency versions, inference latency benchmarks, and A/B test results. This enables governance, rollback, and audit trails required by regulations', 'Model registries replace the need for version control', 'Model registries are only needed for models larger than 1B parameters', 'A model registry only stores model files'], correctAnswer: 0, explanation: 'Beyond model weights, a production registry (MLflow Model Registry, Vertex AI Model Registry, SageMaker Model Registry) tracks: (1) lineage: training data hash, code commit, parent experiment, (2) metrics: accuracy, latency, throughput across hardware, (3) governance: approval status, reviewer, deployment history, (4) card: intended use, known limitations, fairness metrics, (5) dependencies: framework version, custom ops, (6) deployment: which endpoints serve which version, canary %, (7) monitoring: drift alerts linked to this model version. This is essential for ML governance frameworks (EU AI Act, SOC2).', tags: ['model-registry', 'governance', 'lineage', 'model-card'] },
  { id: 'ai-engineer-mlops-l4-003', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Feature Stores', question: 'What is the dual-compute problem that feature stores solve?', options: ['Feature stores provide a unified interface for feature computation that serves both training (batch, historical) and inference (real-time, point-in-time). Without a feature store, teams often implement feature logic twice — once in Python for training and once in Java/SQL for serving — leading to training-serving skew. Feature stores like Feast/Tecton compute features once and serve them consistently to both pipelines', 'Feature stores only cache database queries', 'The dual-compute problem only affects companies with more than 1000 ML engineers', 'Feature stores are only needed for real-time inference'], correctAnswer: 0, explanation: 'The dual-compute problem: training needs features computed on historical data (batch), serving needs the same features computed in real-time on fresh data. If implemented separately, subtle differences (different aggregation windows, off-by-one errors, different libraries) cause training-serving skew — the model sees different feature values at inference vs training. Feature stores solve this by: (1) defining features once in a shared registry, (2) materializing features to offline (batch) and online (low-latency) stores, (3) providing point-in-time correct joins for training (preventing future data leakage).', tags: ['feature-store', 'training-serving-skew', 'feast', 'point-in-time'] },
  { id: 'ai-engineer-mlops-l4-004', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Pipeline Orchestration', question: 'What are the trade-offs between Airflow, Kubeflow Pipelines, and Prefect for ML pipeline orchestration?', options: ['Orchestration tools are unnecessary for ML pipelines', 'Only Kubeflow can run on Kubernetes', 'All orchestration tools are identical in capability', 'Airflow: mature, DAG-based, strong scheduling but weak at dynamic pipelines and containerization. Kubeflow Pipelines: Kubernetes-native with per-step containers and artifact tracking, ideal for GPU workloads but complex setup. Prefect: Python-native with dynamic DAGs and better error handling, but less battle-tested for large-scale ML. Each trades simplicity for different ML-specific capabilities like GPU scheduling, artifact lineage, and caching'], correctAnswer: 3, explanation: 'Airflow: industry standard, rich ecosystem, but tasks are defined in Python at DAG parse time (static), GPU support requires custom operators, and it was designed for ETL not ML. Kubeflow Pipelines: each step is a container on K8s, natural GPU support, built-in artifact tracking and caching, but steep learning curve and K8s dependency. Prefect: dynamic task generation (loops, conditionals at runtime), Pythonic API, good for experimentation. Other options: Metaflow (Netflix, strong data science UX), ZenML (framework-agnostic, pluggable). Choice depends on existing infrastructure, team expertise, and scale requirements.', tags: ['airflow', 'kubeflow', 'prefect', 'pipeline-orchestration'] },
  { id: 'ai-engineer-mlops-l4-005', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Model Drift', question: 'What is the difference between data drift, concept drift, and prediction drift, and how should each be monitored?', options: ['Retraining the model weekly eliminates all drift concerns', 'Drift only occurs in time-series models', 'Data drift: P(X) changes (input distribution shifts). Concept drift: P(Y|X) changes (the relationship between inputs and outcomes changes). Prediction drift: P(Ŷ) changes (model output distribution shifts). Data drift is detected with statistical tests (KS, PSI) on features. Concept drift requires ground truth labels (often delayed). Prediction drift is an early proxy for concept drift when labels are unavailable', 'All types of drift are detected the same way'], correctAnswer: 2, explanation: 'Data drift: features shift (e.g., user demographics change). Detect via: KS test, PSI (Population Stability Index), MMD on feature distributions. Concept drift: the world changes (e.g., COVID changes buying patterns). Detect via: monitoring actual vs predicted when labels arrive, or proxy metrics (conversion rates). Prediction drift: model outputs change even if you cannot see labels yet. Monitor: output distribution (mean prediction, class probabilities). Monitoring stack: (1) feature distributions (Evidently, Whylabs), (2) prediction distributions, (3) business KPIs. React: retrain on recent data, adjust decision thresholds, or trigger alerts.', tags: ['drift', 'monitoring', 'psi', 'concept-drift'] },
  { id: 'ai-engineer-mlops-l4-006', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'CI/CD for ML', question: 'How does CI/CD for ML differ from traditional software CI/CD?', options: ['ML models do not need CI/CD pipelines', 'CI/CD for ML only needs to check code syntax', 'ML CI/CD is identical to software CI/CD', 'ML CI/CD must additionally validate data quality (schema checks, distribution tests), test model quality (evaluation on held-out sets, regression tests against baseline), validate training reproducibility (fixed seeds pass), and test inference performance (latency, throughput). The "build" step includes training, which may take hours/days and require GPUs. CD includes gradual rollout with automated rollback based on online metrics, not just deployment success'], correctAnswer: 3, explanation: 'Software CI: lint → unit test → integration test → deploy. ML CI adds: (1) data validation: Great Expectations/Pandera check schema, ranges, distributions, (2) training tests: model trains without errors, converges, beats baseline metric, (3) evaluation: comprehensive metric suite on holdout + slice-based analysis, (4) performance: inference latency < SLA on target hardware. ML CD adds: (1) model registry promotion (staging → production), (2) canary deployment (serve new model to 5%, compare metrics), (3) shadow mode (run new model alongside old, compare outputs without serving), (4) automated rollback if online metrics degrade. Total pipeline: code change → data check → train → evaluate → register → deploy → monitor.', tags: ['cicd', 'ml-pipeline', 'testing', 'deployment'] },
  { id: 'ai-engineer-mlops-l4-007', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Data Versioning', question: 'How does DVC (Data Version Control) handle large ML datasets alongside Git?', options: ['DVC requires a separate version control system for data', 'DVC replaces large files in Git with small metadata files (.dvc) containing content hashes. The actual data is stored in remote storage (S3, GCS, Azure). Git tracks the .dvc files, enabling data versioning alongside code. DVC pipelines define DAGs of data processing steps with dependency tracking and caching — if inputs have not changed, steps are skipped. This enables reproducible, versioned data pipelines without bloating the Git repository', 'DVC only works with CSV files', 'DVC stores all data directly in Git'], correctAnswer: 1, explanation: 'DVC workflow: dvc add large_dataset/ → creates large_dataset.dvc (md5 hash + metadata) + .gitignore entry. Git tracks the .dvc file; DVC stores data content-addressed in remote storage. dvc push uploads data; dvc pull downloads. Pipeline: dvc.yaml defines stages with deps (inputs) and outs (outputs). dvc repro runs only stages whose dependencies changed. Benefits: (1) exact data version for every code commit, (2) efficient storage via content hashing (deduplication), (3) reproducible pipelines with caching, (4) experiment management with dvc exp. Works with any storage backend and integrates with existing Git workflow.', tags: ['dvc', 'data-versioning', 'content-hashing', 'pipeline'] },
  { id: 'ai-engineer-mlops-l4-008', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Model Monitoring', question: 'What is the "ground truth delay" problem in ML monitoring and how can proxy metrics help?', options: ['Ground truth is always available immediately', 'Proxy metrics are always more accurate than ground truth', 'In many ML systems, the true label is only known after a delay (fraud detection: days/weeks for investigation; recommendation: delayed purchase; medical: follow-up months later). During this gap, direct model accuracy cannot be measured. Proxy metrics bridge the gap: prediction confidence distributions, feature drift detection, prediction distribution stability, and business KPIs (click-through rate, conversion) serve as early warning signals before ground truth arrives', 'Ground truth delay only affects batch prediction systems'], correctAnswer: 2, explanation: 'Example: credit default model — the label "did they default?" is only known 6-12 months after prediction. During that time: (1) monitor feature distributions for drift (PSI > 0.2 → investigate), (2) track prediction distribution (if the model suddenly predicts 2x more defaults, something changed), (3) use early proxies (missed payment within 30 days as proxy for eventual default), (4) compare model confidence distributions to calibration curves from training. Evidently, Whylabs, and Arize provide drift detection; custom dashboards track business KPIs. Automated alerts trigger investigation or retraining when proxies cross thresholds.', tags: ['ground-truth-delay', 'proxy-metrics', 'monitoring', 'drift-detection'] },
  { id: 'ai-engineer-mlops-l4-009', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Infrastructure', question: 'What is the ML platform "inner loop vs outer loop" concept?', options: ['Inner and outer loops refer to nested for loops in training code', 'The inner loop is the rapid experiment iteration cycle (modify code → train → evaluate → iterate), requiring fast feedback, interactive notebooks, and GPU access. The outer loop is the production pipeline (data ingestion → training → validation → deployment → monitoring), requiring reliability, automation, and governance. Effective ML platforms must support both: inner loop for data scientists exploring, outer loop for production ML engineers operating', 'ML platforms only need to support the outer loop', 'The inner loop is only used during the first week of a project'], correctAnswer: 1, explanation: 'Inner loop (experimentation): Jupyter notebooks, W&B experiment tracking, interactive GPU sessions, fast iteration (minutes to hours). Needs: flexibility, quick starts, easy visualization. Outer loop (production): automated pipelines, model registry, deployment, monitoring. Needs: reliability, reproducibility, governance. Many ML platform failures come from optimizing only one: (1) only inner loop → "it works on my laptop" syndrome, no production path, (2) only outer loop → heavy process prevents rapid experimentation. Successful platforms (Uber Michelangelo, Google TFX, Netflix Metaflow) bridge both with seamless promotion from experiments to production.', tags: ['ml-platform', 'inner-loop', 'outer-loop', 'experimentation'] },
  { id: 'ai-engineer-mlops-l4-010', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Testing', question: 'What types of tests should an ML system have beyond standard unit tests?', options: ['Testing is unnecessary if the model achieves high accuracy on the test set', 'Standard unit tests are sufficient for ML systems', 'ML systems need: data tests (schema validation, distribution checks, no leakage), model tests (performance above threshold, no regression vs baseline, fairness across slices), infrastructure tests (training completes in time budget, model fits in serving memory), behavioral tests (CheckList-style: invariance, directional, minimum functionality), and integration tests (end-to-end pipeline from raw data to prediction). Each catches different failure modes that unit tests miss', 'ML systems only need to test prediction accuracy'], correctAnswer: 2, explanation: 'ML testing taxonomy: (1) Data tests: validate schema, check for nulls/outliers, assert train/test distribution similarity, detect label leakage, (2) Model tests: accuracy > threshold on holdout, no regression vs previous model, performance on critical slices (demographics, edge cases), calibration check, (3) Behavioral tests (Ribeiro et al. 2020): invariance (changing irrelevant input shouldn\'t change output), directional (known transformations should predictably change output), MFT (minimum functionality on critical examples), (4) Infrastructure: training within time/cost budget, model size fits deployment target, latency meets SLA, (5) Integration: full pipeline reproducibility test.', tags: ['ml-testing', 'behavioral-testing', 'data-validation', 'regression-testing'] },
  { id: 'ai-engineer-mlops-l4-011', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Model Serving', question: 'What is the difference between online prediction, batch prediction, and streaming prediction in ML serving?', options: ['Batch prediction is always cheaper than online prediction', 'Streaming prediction requires specialized hardware', 'Online prediction: synchronous request-response with strict latency SLAs (p99 < 100ms), requires always-on GPU/CPU servers. Batch prediction: pre-compute predictions for all items periodically (hourly/daily), store results in a database, serve from cache. Streaming prediction: process events from a message queue (Kafka) in near-real-time, useful when predictions must react to events but sub-second latency is not needed. Each has different cost, freshness, and infrastructure implications', 'All prediction modes have the same latency requirements'], correctAnswer: 2, explanation: 'Trade-offs: Online — freshest predictions, handles unseen inputs, but requires provisioned GPU servers 24/7 (expensive, cold start latency). Batch — cheapest per prediction (large batches maximize GPU utilization), but stale by the time they are served (computed hours ago). Streaming — middle ground: processes events from Kafka/Kinesis with seconds-to-minutes latency, good for feature computation + prediction. Choice: recommendation reranking → online (user-specific, real-time). Email campaign targeting → batch (compute overnight). Fraud detection → streaming (react to transactions within minutes). Many systems combine: batch for most, online for critical paths.', tags: ['model-serving', 'batch-prediction', 'online-prediction', 'streaming'] },
  { id: 'ai-engineer-mlops-l4-012', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Shadow Deployment', question: 'What is shadow (dark) deployment for ML models and when should it be used?', options: ['Shadow deployment doubles the hardware cost permanently', 'Shadow deployment immediately replaces the production model', 'Shadow deployment is only needed for the first model deployment', 'Shadow deployment runs the new model alongside the production model, processing the same live traffic, but only the production model\'s predictions are served to users. The shadow model\'s predictions are logged for comparison. This enables safe evaluation on real traffic patterns without risk, detecting issues that offline evaluation misses: latency problems, edge cases in production data, and prediction distribution differences'], correctAnswer: 3, explanation: 'Shadow deployment workflow: (1) deploy new model alongside current, (2) route all live requests to both, (3) serve only production model\'s response, (4) log shadow model responses, (5) compare metrics: accuracy (when labels arrive), latency, error rates, prediction distribution, (6) if shadow model performs well, promote to canary → full production. Critical for: (1) first model deployment (shadow vs heuristic baseline), (2) major model architecture changes, (3) models affecting revenue/safety. Cost: ~2x compute during shadow period, but avoids costly production failures. Can be combined with A/B testing: shadow first, then controlled A/B.', tags: ['shadow-deployment', 'canary', 'safe-deployment', 'model-comparison'] },
  { id: 'ai-engineer-mlops-l4-013', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Labeling', question: 'What is programmatic labeling (Snorkel paradigm) and how does it scale annotation?', options: ['Programmatic labeling cannot work without at least 10,000 manual labels', 'Programmatic labeling always produces perfect labels', 'Programmatic labeling uses labeling functions (LFs) — heuristic rules, knowledge bases, or weak models — that each provide noisy labels. A label model combines multiple LFs using their agreement/disagreement patterns to estimate true labels, even when individual LFs are inaccurate. This enables labeling thousands of examples per hour instead of hundreds, while quantifying label uncertainty. Snorkel\'s label model handles LF correlations and conflicts using a generative model', 'Programmatic labeling uses LLMs to label all data directly'], correctAnswer: 2, explanation: 'Snorkel (Ratner et al. 2017): (1) define labeling functions: keyword rules (if "urgent" in text → positive), pattern matching, external KB lookups, or small model predictions, (2) each LF labels a subset of data (may abstain on many), (3) label model estimates LF accuracies and correlations from their agreements/disagreements (no ground truth needed), (4) generates probabilistic labels for all data, (5) train end model on probabilistic labels. Benefits: domain expert writes 20 LFs in a day instead of manually labeling 10K examples. LF quality is automatically estimated. Modern extension: using LLM-generated labels as additional LFs in the Snorkel framework, with the label model handling their noise.', tags: ['snorkel', 'programmatic-labeling', 'labeling-functions', 'weak-supervision'] },
  { id: 'ai-engineer-mlops-l4-014', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Cost Optimization', question: 'What strategies reduce GPU training costs in cloud environments?', options: ['Mixed-precision training doubles the cost', 'Key strategies: (1) spot/preemptible instances (60-90% cheaper) with checkpointing for fault tolerance, (2) mixed-precision training (2x throughput on same GPU), (3) right-sizing: match GPU type to workload (A10G for inference, H100 for large training), (4) gradient accumulation to reduce GPU count, (5) auto-scaling training clusters based on experiment queue, (6) data-parallel training with efficient communication (NCCL, gradient compression), (7) training on reserved instances for predictable long workloads', 'Cloud GPU costs cannot be optimized', 'Using the most expensive GPU is always the most cost-effective'], correctAnswer: 1, explanation: 'Spot instances (AWS) / Preemptible VMs (GCP): 60-90% discount, but can be interrupted. Mitigation: checkpoint every N minutes, resume from last checkpoint. For a 24-hour training job at $32/hr (8×A100 on-demand): $768 → spot at $10/hr: ~$240 + overhead ≈ $300 (61% savings). Mixed precision: FP16/BF16 compute doubles throughput on Ampere+ GPUs. Right-sizing: inference on A10G ($1/hr) vs A100 ($4/hr) if the model fits. Gradient accumulation: simulate 64 batch size on 4 GPUs instead of 8. Reserved instances: 30-40% savings for predictable training clusters. Also: distill large models to smaller ones that are cheaper to serve.', tags: ['cost-optimization', 'spot-instances', 'mixed-precision', 'gpu-utilization'] },
  { id: 'ai-engineer-mlops-l4-015', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Data Quality', question: 'What is the "data flywheel" and how does it create a compounding advantage in ML systems?', options: ['Data flywheels only apply to recommendation systems', 'A data flywheel is a data storage optimization technique', 'The data flywheel is a virtuous cycle: better model → better product → more users → more data → better model. Each iteration improves data quality and quantity, compounding model performance. Key elements: logging production predictions and outcomes, identifying failure modes through monitoring, targeted data collection for weak areas, active learning to prioritize high-value labels, and continuous retraining. Companies with established flywheels have a durable competitive advantage', 'The data flywheel stops providing benefits after the first iteration'], correctAnswer: 2, explanation: 'The data flywheel (coined at Tesla/Google): (1) Deploy model → (2) Users interact → (3) Log interactions + outcomes → (4) Identify failure modes (hard examples, new patterns) → (5) Collect/label data for failures → (6) Retrain improved model → back to (1). Each cycle: model improves on real-world distribution, product quality increases, user base grows, more diverse data is collected. Key engineering: auto-labeling pipelines (reduce human labeling cost), active learning (prioritize uncertain examples), feedback loops (user corrections become training data). Companies like Google Search, Tesla Autopilot, and Spotify recommendations have multi-year flywheel advantages.', tags: ['data-flywheel', 'continuous-learning', 'active-learning', 'competitive-advantage'] },
  { id: 'ai-engineer-mlops-l4-016', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Configuration Management', question: 'Why is Hydra (or similar config management) critical for ML experiment management?', options: ['Hard-coding hyperparameters in source code is the best practice', 'Configuration management slows down ML development', 'ML experiments only need command-line arguments', 'Hydra enables hierarchical configuration composition: base config + model overrides + data overrides + environment overrides, supporting multi-run sweeps, config versioning, and reproducibility. ML experiments have many interacting parameters (model architecture, optimizer, data preprocessing, augmentation, hardware) that command-line arguments cannot manage. Hydra\'s config groups, defaults lists, and multirun support enable systematic experimentation with full configuration tracking'], correctAnswer: 3, explanation: 'ML experiments have 50-200+ configuration parameters across model, data, training, and infrastructure. Problems without structured config: (1) parameters scattered across code, (2) experiments cannot be reproduced (which args were used?), (3) sweeps require manual scripts, (4) environment-specific overrides are ad-hoc. Hydra: define config.yaml hierarchy → compose configs → override from CLI (--model.lr=0.001) → auto-log full config to output dir. Multirun: --multirun model.lr=0.001,0.01,0.1 launches 3 jobs. Config groups: swap entire model architectures by name. Integrates with MLflow/W&B for config logging. Alternatives: OmegaConf, gin-config, Lightning CLI.', tags: ['hydra', 'configuration', 'experiment-management', 'reproducibility'] },
  { id: 'ai-engineer-mlops-l4-017', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Containerization', question: 'Why are Docker containers essential for ML deployment and what ML-specific challenges arise?', options: ['Docker ensures consistent environments across development, training, and serving, eliminating "works on my machine" issues. ML-specific challenges: (1) large image sizes (PyTorch + CUDA > 10GB), (2) GPU driver compatibility (NVIDIA Container Toolkit), (3) multi-stage builds needed to separate training deps from serving, (4) CUDA version must match GPU driver, (5) Python dependency resolution is slow. Best practices: use NVIDIA base images, multi-stage builds, layer caching for dependencies, and distroless images for minimal serving containers', 'Docker containers cannot access GPUs', 'Docker is unnecessary for ML deployment', 'ML Docker images should always include all training and serving dependencies'], correctAnswer: 0, explanation: 'ML Docker challenges: (1) Size: pytorch + cuda + transformers → 15GB+ images. Mitigation: multi-stage builds (stage 1: install deps, stage 2: copy only runtime needs), use slim base images, (2) GPU: need nvidia-container-toolkit on host, base image must match host CUDA driver (forward compatible within major version), (3) Dependency hell: PyTorch GPU + TensorFlow + specific CUDA → conflict resolution. Pin everything in requirements.txt/poetry.lock, (4) Build time: pip install takes 10+ minutes. Cache pip/conda layers early, use pip wheel cache. Production: separate training image (includes data processing + training code) from serving image (model + inference code only, minimal deps for smaller attack surface and faster scaling).', tags: ['docker', 'containerization', 'gpu', 'nvidia-container-toolkit'] },
  { id: 'ai-engineer-mlops-l4-018', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Retraining', question: 'What triggers should initiate model retraining and how do you prevent unnecessary retraining?', options: ['Retraining should only happen once per year', 'Models never need retraining once they reach target accuracy', 'Models should be retrained on a fixed daily schedule regardless of need', 'Retraining triggers should include: significant data drift (PSI > threshold), degraded online metrics (accuracy/revenue below threshold), sufficient new labeled data accumulated, concept drift detection, or scheduled cadence for slowly-evolving domains. Prevent unnecessary retraining by: checking if new data significantly differs from training data, running challenger evaluation before deploying retrained model, and using confidence intervals on metric improvements to avoid noise-driven retraining'], correctAnswer: 3, explanation: 'Intelligent retraining policy: (1) Drift-triggered: monitor PSI/KS on key features, trigger when drift exceeds threshold, (2) Performance-triggered: when online accuracy or business KPI drops below threshold (requires ground truth), (3) Data-triggered: when N new labeled examples accumulate (ensures meaningful data delta), (4) Scheduled: weekly/monthly as a safety net for gradual drift. Prevent waste: (a) evaluate retrained model on holdout — only deploy if statistically significant improvement (paired t-test, >0.5% accuracy gain), (b) early stopping during retraining if validation doesn\'t improve, (c) incremental training on new data only (fine-tune rather than retrain from scratch when appropriate).', tags: ['retraining', 'triggers', 'drift-based', 'continuous-training'] },
  { id: 'ai-engineer-mlops-l4-019', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'A/B Testing', question: 'What are the statistical pitfalls of A/B testing for ML model comparisons?', options: ['Pitfalls include: (1) peeking at results before reaching statistical significance (inflates false positive rate), (2) multiple comparisons without correction (testing 10 metrics guarantees false positives), (3) network effects violating independence (SUTVA: users influence each other), (4) novelty/primacy effects (users initially engage differently with new models), (5) Simpson\'s paradox (model B wins overall but loses in every subgroup). ML-specific: model prediction variance adds noise, requiring larger sample sizes than standard A/B tests', 'Running the test for one day is always sufficient', 'A/B testing for ML has no statistical pitfalls', 'A/B tests always give correct results'], correctAnswer: 0, explanation: 'ML A/B testing challenges beyond standard A/B: (1) Peeking: checking p-values daily with optional stopping inflates type I error from 5% to 26%. Use sequential testing (CUPED) or fixed sample sizes, (2) Multiple metrics: if you check 20 metrics at α=0.05, expect 1 false positive. Apply Bonferroni or FDR correction, (3) Interference: in recommendation/marketplace, treating one user affects others. Use cluster randomization or switchback experiments, (4) Variance: ML model outputs are noisier than simple UI changes, requiring 2-5x more traffic for significance, (5) Long-term effects: short tests miss long-term user behavior changes. Solutions: use cuped variance reduction, pre-experiment power analysis, and pre-register primary metrics.', tags: ['ab-testing', 'statistical-significance', 'peeking', 'multiple-comparisons'] },
  { id: 'ai-engineer-mlops-l4-020', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Governance', question: 'What does the EU AI Act require for high-risk AI systems from an MLOps perspective?', options: ['The EU AI Act has no technical requirements', 'The EU AI Act only applies to models with more than 1B parameters', 'Only US companies need to comply with the EU AI Act', 'The EU AI Act requires: risk management systems (identify and mitigate risks throughout lifecycle), data governance (training data quality, relevance, representativeness), technical documentation (model cards, architecture, training details), record-keeping (logging for traceability), transparency (users informed they are interacting with AI), human oversight provisions, and accuracy/robustness standards. MLOps must implement: audit trails, data lineage, model monitoring, bias testing, and documentation automation to comply'], correctAnswer: 3, explanation: 'High-risk AI (hiring, credit scoring, medical devices, law enforcement) under EU AI Act Article 9-15 requires: (1) Risk management: continuous identification and mitigation of risks (→ model monitoring, fairness dashboards), (2) Data governance: training data must be relevant, representative, free of errors (→ data validation pipelines, bias audits), (3) Record-keeping: automatic logging of operations for traceability (→ experiment tracking, model registry with full lineage), (4) Transparency: clear documentation of capabilities and limitations (→ automated model cards), (5) Human oversight: ability for humans to override the system (→ confidence thresholds, escalation mechanisms), (6) Accuracy and robustness: testing throughout lifecycle (→ continuous evaluation, adversarial testing).', tags: ['eu-ai-act', 'governance', 'compliance', 'high-risk-ai'] },
  { id: 'ai-engineer-mlops-l4-021', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Model Optimization', question: 'What is the ONNX Runtime and how does it improve inference performance across hardware platforms?', options: ['ONNX Runtime is a cross-platform inference engine that takes ONNX format models and applies hardware-specific optimizations: graph optimization (constant folding, operator fusion), execution provider backends (CUDA, TensorRT, OpenVINO, CoreML), and quantization. It enables deploying the same model to GPU servers, CPU servers, mobile devices, and edge hardware with optimized performance per target, without rewriting inference code', 'ONNX Runtime is slower than running models in their native framework', 'ONNX only supports PyTorch models', 'ONNX Runtime only works with NVIDIA GPUs'], correctAnswer: 0, explanation: 'ONNX (Open Neural Network Exchange): framework-agnostic model format. ONNX Runtime (ORT): (1) graph optimizations: fuse Conv+BN+ReLU → single op, constant folding, dead code elimination, (2) execution providers: CUDAExecutionProvider (GPU), TensorrtExecutionProvider (INT8/FP16 on NVIDIA), OpenVINOExecutionProvider (Intel CPUs/VPUs), CoreMLExecutionProvider (Apple Silicon). Typical speedups: 2-4x over native PyTorch/TensorFlow inference due to optimizations. Workflow: train in PyTorch → torch.onnx.export → ORT inference. ORT also supports: quantization (dynamic/static INT8), transformer-specific optimizations (fused attention), and IO binding (zero-copy GPU tensor passing).', tags: ['onnx', 'onnx-runtime', 'inference-optimization', 'cross-platform'] },
  { id: 'ai-engineer-mlops-l4-022', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Experiment Design', question: 'What is the difference between interleaving experiments and A/B tests for ranking model evaluation?', options: ['Interleaving can only compare two models at a time', 'A/B testing splits users between control and treatment groups, requiring large sample sizes because user-level metrics are noisy. Interleaving merges results from two rankers into a single list shown to every user, then credits clicks to the originating ranker. This paired comparison is 10-100x more sensitive because it controls for user-level confounds (same user sees both models\' results), detecting smaller differences with less traffic', 'Interleaving and A/B testing are identical methods', 'A/B testing is always more sensitive than interleaving'], correctAnswer: 1, explanation: 'A/B test for search/recommendation: half the users see ranker A, half see ranker B. Variance comes from user differences (some users click more), requiring millions of queries for significance. Interleaving (Team Draft, Balanced): for each query, interleave results from A and B into one list. Each click is attributed to A or B based on which ranker produced that result. The within-user comparison eliminates user-level variance, making it 10-100x more statistically efficient. Netflix and Google use interleaving for initial ranker comparison, then A/B tests for full metric evaluation (revenue, retention, etc.).', tags: ['interleaving', 'ab-testing', 'ranking', 'statistical-sensitivity'] },
  { id: 'ai-engineer-mlops-l4-023', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Debugging', question: 'What systematic approach should be used when a deployed ML model\'s performance degrades?', options: ['Model degradation is always caused by concept drift', 'There is no systematic approach; try random fixes until performance improves', 'Systematic debugging: (1) verify the metric (is the monitoring correct?), (2) check for data issues (schema changes, missing features, upstream pipeline failures), (3) analyze which segments are affected (geographic, demographic, temporal), (4) compare current data distributions to training data (drift analysis), (5) check for concept drift vs data drift (has the world changed or just the inputs?), (6) examine recent deployments (model or infrastructure changes), (7) determine if the fix is retraining, data pipeline repair, or reverting a change', 'Always retrain the model immediately when performance drops'], correctAnswer: 2, explanation: 'Common root causes by frequency: (1) upstream data pipeline change (40%): a feature stopped updating, schema changed, or null values increased. Fix: repair pipeline, not retrain, (2) data distribution shift (25%): seasonal changes, new user segments. Fix: retrain on recent data, (3) concept drift (15%): actual relationship changed (COVID, new regulations). Fix: retrain with recent data, potentially new features, (4) infrastructure issue (10%): model serving bug, wrong model version deployed. Fix: rollback, (5) label quality degradation (10%): labeling pipeline broke. Fix: audit labels. Key tool: slice-based analysis (which feature values degrade most?) pinpoints the root cause faster than aggregate metrics.', tags: ['debugging', 'model-degradation', 'root-cause', 'slice-analysis'] },
  { id: 'ai-engineer-mlops-l4-024', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'ML Architecture', question: 'What is the microservice vs monolithic architecture trade-off for ML systems?', options: ['Monolithic: single service handles preprocessing + inference + postprocessing. Simpler to develop and debug, lower latency (no network hops), but harder to scale independently and version components. Microservices: separate services for feature computation, model inference, postprocessing. Enables independent scaling (inference on GPU, features on CPU), independent versioning, and team autonomy, but adds latency, complexity, and distributed system challenges', 'Microservices are always better for ML systems', 'The choice has no impact on system performance', 'ML systems should never use microservices'], correctAnswer: 0, explanation: 'Monolithic ML service: predict(request) → preprocess → inference → postprocess → response. All in one container. Pros: simple deployment, low latency, easy debugging. Cons: can\'t scale inference independently from preprocessing, model update requires full redeployment. Microservice ML: API gateway → feature service → model service → business logic service. Pros: scale GPU inference independently, A/B test model service without touching features, different teams own different services. Cons: network latency between services (adds 5-20ms), distributed tracing needed for debugging, more complex deployment. Guideline: start monolithic, decompose when scaling/team/versioning pain appears.', tags: ['microservices', 'monolithic', 'ml-architecture', 'scaling'] },
  { id: 'ai-engineer-mlops-l4-025', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Kubernetes', question: 'How does KServe (formerly KFServing) simplify ML model serving on Kubernetes?', options: ['KServe requires manual configuration of load balancing and scaling', 'KServe cannot scale to zero pods', 'KServe only supports TensorFlow models', 'KServe provides a Kubernetes CRD (Custom Resource Definition) for ML serving with: autoscaling (including scale-to-zero for cost savings), canary rollouts with traffic splitting, multi-model serving (many models per GPU), built-in support for common frameworks (TensorFlow, PyTorch, sklearn, XGBoost), transformer/predictor/explainer component architecture, and GPU scheduling. It abstracts away Kubernetes complexity behind a simple InferenceService YAML spec'], correctAnswer: 3, explanation: 'KServe InferenceService: define model (framework, storage URI, GPU requirements) → KServe handles: (1) Knative-based autoscaling with scale-to-zero (no GPU cost when idle), (2) canary deployments (90/10 traffic split between old/new model), (3) transformer component for preprocessing (can be a separate container), (4) model loading from S3/GCS/PVC, (5) batching (accumulate requests for batch inference), (6) multi-model serving (ModelMesh: 100s of models per GPU with model loading/unloading), (7) inference graph (chain multiple models). Compared to raw K8s Deployments: dramatically reduces boilerplate for common ML serving patterns.', tags: ['kserve', 'kubernetes', 'model-serving', 'autoscaling'] },
  { id: 'ai-engineer-mlops-l4-026', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'LLMOps', question: 'How does LLMOps differ from traditional MLOps?', options: ['LLMOps eliminates the need for model monitoring', 'LLMOps only applies to fine-tuned LLMs, not API-based systems', 'LLMOps introduces: prompt management and versioning (prompts are a key artifact), evaluation via LLM-as-Judge instead of static metrics, RAG pipeline orchestration (chunking, embedding, retrieval configuration), guardrails as first-class components, cost monitoring per token, semantic caching for API cost reduction, and response quality monitoring (hallucination detection, faithfulness checks). The experimentation loop shifts from model training to prompt/retrieval optimization', 'LLMOps and MLOps are identical practices'], correctAnswer: 2, explanation: 'Key LLMOps differences: (1) Prompt engineering replaces model training as the primary iteration loop — prompts need version control, A/B testing, and regression testing, (2) Evaluation: static test sets are insufficient; LLM-as-Judge, human evaluation, and behavioral tests needed, (3) RAG pipeline management: chunk size, overlap, embedding model, reranker — all are hyperparameters to optimize, (4) Cost: token-based pricing requires monitoring and optimization (caching, prompt compression, model routing), (5) Safety: guardrails, content filtering, PII detection are production requirements. Tools: LangSmith, Langfuse, Phoenix for tracing; PromptLayer, Humanloop for prompt management; RAGAS for RAG evaluation.', tags: ['llmops', 'prompt-management', 'rag-pipeline', 'cost-monitoring'] },
  { id: 'ai-engineer-mlops-l4-027', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Data Pipelines', question: 'What is the medallion architecture (bronze-silver-gold) for ML data pipelines?', options: ['The medallion architecture is a type of model architecture', 'The medallion architecture only works with streaming data', 'The medallion architecture organizes data in three layers: Bronze (raw ingested data, append-only, schema-on-read), Silver (cleaned, validated, deduplicated data with enforced schemas), and Gold (aggregated, feature-engineered data ready for ML training/serving). Each layer adds quality: bronze captures everything, silver ensures correctness, gold provides business/ML-ready features. This separation enables data reprocessing and multiple ML teams to share validated data', 'All data should be stored in a single layer for simplicity'], correctAnswer: 2, explanation: 'Bronze: raw data as-is from sources (APIs, databases, logs). Append-only, immutable — enables reprocessing. Stored in Parquet/Delta Lake. Silver: cleaned data — nulls handled, schemas enforced (Great Expectations), duplicates removed, PII masked. This is the "single source of truth." Gold: task-specific features — aggregations, joins, transformations for specific ML models. Multiple gold tables can exist for different use cases, all built from the same silver data. Benefits: (1) raw data preserved for debugging, (2) cleaning logic centralized in bronze→silver, (3) multiple teams build gold layers without duplicating cleaning effort. Implemented with: Delta Lake, Apache Iceberg, or Apache Hudi on top of object storage.', tags: ['medallion-architecture', 'data-pipeline', 'delta-lake', 'data-quality'] },
  { id: 'ai-engineer-mlops-l4-028', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Observability', question: 'What is the difference between ML monitoring and ML observability?', options: ['Only monitoring is needed for production ML systems', 'Monitoring tracks predefined metrics and alerts on thresholds (reactive: "accuracy dropped below 95%"). Observability enables querying arbitrary questions about system behavior using detailed telemetry (proactive: "why did accuracy drop? which user segment? which features drifted?"). Observability requires: fine-grained logging (per-prediction features + outputs), distributed tracing through the pipeline, and tools for ad-hoc slicing and analysis', 'Observability is unnecessary if monitoring is in place', 'Monitoring and observability are the same thing'], correctAnswer: 1, explanation: 'Monitoring: dashboard of predefined metrics (accuracy, latency, throughput, error rate). Alerts when thresholds are crossed. Answers: "is something wrong?" Observability: rich telemetry enabling ad-hoc investigation. Answers: "what is wrong and why?" Requirements: (1) log every prediction with features, output, confidence, and metadata, (2) distributed tracing: request ID from API → feature store → model → post-processing, (3) arbitrary slice analysis: accuracy for "users from Germany" or "queries containing medical terms," (4) correlation: which feature changes correlate with accuracy drops? Tools: Arize, Whylabs (drift), Evidently (reports), custom ELK/Grafana stacks for low-level observability. The shift from monitoring to observability mirrors the SRE evolution in traditional software.', tags: ['observability', 'monitoring', 'telemetry', 'debugging'] },
  { id: 'ai-engineer-mlops-l4-029', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Multi-Model', question: 'What is a champion-challenger model deployment pattern?', options: ['Champion-challenger requires manual comparison by a data scientist', 'Champion-challenger means training multiple models simultaneously', 'Only one model can ever be in production at a time', 'Champion-challenger runs the current production model (champion) and one or more challenger models on the same traffic. The champion serves all predictions while challengers run in shadow mode or receive a small traffic percentage. Challengers are promoted to champion when they demonstrate statistically significant improvement over a defined evaluation period. This enables continuous model improvement with minimal risk'], correctAnswer: 3, explanation: 'Champion-challenger workflow: (1) champion serves 100% of traffic (or 95%), (2) challengers are: newly trained models, different architectures, or retrained-on-recent-data versions, (3) evaluation: compare on live traffic metrics (or shadow mode), (4) promotion: when challenger beats champion by statistically significant margin on primary metric, promote to champion. Automation: ML platform compares metrics over N days, runs statistical test, auto-promotes or alerts for human review. Benefits: (1) continuous improvement without manual intervention, (2) safe — champion always serves most traffic, (3) multiple challengers can compete simultaneously. Implemented in: SageMaker (production variants), Seldon Core, custom platforms.', tags: ['champion-challenger', 'deployment', 'model-comparison', 'continuous-improvement'] },
  { id: 'ai-engineer-mlops-l4-030', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Incident Response', question: 'What should an ML-specific incident response playbook include?', options: ['ML systems use the same incident response as traditional software', 'Retraining the model always fixes ML incidents', 'ML incidents never require immediate response', 'ML incident playbook should include: (1) detection — which monitoring alert fired and why, (2) triage — is it a data issue, model issue, or infrastructure issue, (3) immediate mitigation — rollback to previous model version, switch to rule-based fallback, or disable the feature, (4) root cause analysis — drift report, feature analysis, prediction audit, (5) remediation — fix data pipeline, retrain model, or adjust thresholds, (6) postmortem — document root cause, impact, and preventive measures. ML-specific: includes model version rollback procedures and data snapshot preservation'], correctAnswer: 3, explanation: 'ML-specific incident response additions: (1) Rollback: ability to instantly revert to the previous model version (model registry + blue-green deployment), (2) Fallback: rule-based system or heuristic that can serve while the model is being investigated, (3) Data snapshot: preserve the data that caused the issue before it is overwritten (critical for root cause analysis), (4) Impact assessment: which predictions were affected? Can decisions be reversed? (especially important for financial/medical ML), (5) Communication: notify downstream consumers of model outputs about potential quality issues. Automation: auto-rollback when key metrics drop by >X% for >Y minutes. Key metric: Mean Time To Detect (MTTD) and Mean Time To Recovery (MTTR) for ML systems.', tags: ['incident-response', 'rollback', 'fallback', 'postmortem'] },
  { id: 'ai-engineer-mlops-l4-031', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Caching', question: 'What caching strategies are effective for ML inference and what are the cache invalidation challenges?', options: ['Only the model weights should be cached', 'ML inference should never be cached', 'Caching ML predictions always leads to incorrect results', 'Effective strategies: exact cache (hash input → cached prediction for identical inputs), feature cache (cache expensive feature computations, not predictions), embedding cache (cache vector embeddings for frequent entities), and model result cache (cache predictions for items that don\'t change often). Challenges: cache invalidation when models are updated (all cached predictions are stale), feature freshness (real-time features change), and cache size management for high-cardinality inputs'], correctAnswer: 3, explanation: 'ML caching layers: (1) Input cache: for recommendation systems, cache user-item scores that don\'t need real-time recomputation (invalidate on model update or user action), (2) Feature cache: expensive features (aggregations over 90 days of data) computed once, served from Redis/Memcached, invalidated on time window roll, (3) Embedding cache: user/item embeddings that change slowly, recomputed periodically, (4) Semantic cache: for LLM applications, similar queries return cached responses. Invalidation: model update → bulk invalidate prediction cache (stale predictions from old model). Feature update → invalidate dependent cached features. TTL-based invalidation as safety net. Monitor cache hit rate and stale-prediction rate as observability metrics.', tags: ['caching', 'inference', 'invalidation', 'performance'] },
  { id: 'ai-engineer-mlops-l4-032', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Data Contracts', question: 'What are data contracts and why are they essential for ML pipeline reliability?', options: ['Data contracts are only needed between companies, not teams', 'Schema validation is sufficient; formal contracts add no value', 'Data contracts are legal agreements about data ownership', 'Data contracts are formal specifications between data producers and consumers that define: schema (column names, types), quality expectations (completeness, freshness, value ranges), SLAs (data available by when), and semantic meaning of fields. For ML pipelines, they prevent silent data corruption where an upstream schema change breaks feature computation without raising errors — the contract enforcement catches violations before they corrupt model training'], correctAnswer: 3, explanation: 'Without contracts: upstream team renames a column → feature pipeline silently produces nulls → model trains on corrupted data → production model degrades days later. With contracts: producer and consumer agree on schema + quality rules. Contract enforcement at ingestion rejects non-conforming data and alerts both parties. Implementation: (1) Define contracts in YAML/protobuf (schema, constraints, freshness SLA), (2) Enforce at pipeline boundaries (Great Expectations, Soda), (3) Version contracts alongside code, (4) Alerting: contract violations → block pipeline + notify producer. ML-specific: include statistical constraints (feature distributions, correlation stability) beyond schema validation.', tags: ['data-contracts', 'schema', 'data-quality', 'pipeline-reliability'] },
  { id: 'ai-engineer-mlops-l4-033', language: 'ai-engineer', level: 'level4', category: 'MLOps', subcategory: 'Maturity Model', question: 'What are the levels of ML maturity from ad-hoc to fully automated, and what characterizes each level?', options: ['ML maturity only depends on model accuracy', 'Level 0: Manual — Jupyter notebooks, manual deployment, no monitoring. Level 1: ML Pipeline — automated training pipeline, experiment tracking, basic monitoring. Level 2: CI/CD for ML — automated testing, model validation, canary deployment. Level 3: Continuous Training — automated retraining on drift/schedule, champion-challenger, full observability. Each level builds on the previous, and most organizations should aim for Level 2 before attempting Level 3 to avoid premature automation complexity', 'Level 3 is unnecessary for production ML systems', 'All organizations start at the highest ML maturity level'], correctAnswer: 1, explanation: 'Google\'s MLOps maturity levels: Level 0 (Manual): data scientists train in notebooks, hand off models to engineers for deployment. Pain: slow iteration, no reproducibility. Level 1 (ML Pipeline Automation): automated training pipeline, feature store, experiment tracking. Pain: manual deployment, limited monitoring. Level 2 (CI/CD + CT): automated testing (data, model, integration), automated deployment with validation gates, drift monitoring triggers retraining. Level 3 (Full Automation): continuous training, automated champion-challenger, self-healing (auto-rollback + retrain). Most companies should invest in Level 1-2 infrastructure before attempting Level 3 — premature automation adds complexity without proportional benefit.', tags: ['ml-maturity', 'automation', 'continuous-training', 'mlops-levels'] },
];

export default questions;
